const spendAid = `-- name: SpendAid :one
UPDATE app.players
SET aid_day   = $1,
    aid_given = CASE WHEN aid_day = $1 THEN aid_given + 1 ELSE 1 END
WHERE id = $2
  AND (aid_day IS DISTINCT FROM $1 OR aid_given < $3::int)
RETURNING aid_given
`

type SpendAidParams struct {
	Today    pgtype.Date
	PlayerID uuid.UUID
	PerDay   int32
}

// The day's aid given, spent on the helper's own row.
func (q *Queries) SpendAid(ctx context.Context, arg SpendAidParams) (int16, error) {
	row := q.db.QueryRow(ctx, spendAid, arg.Today, arg.PlayerID, arg.PerDay)
	var aid_given int16
	err := row.Scan(&aid_given)
	return aid_given, err
}

const spendFriendRequest = `-- name: SpendFriendRequest :one
UPDATE app.players
SET friend_req_day = $1,
    friend_reqs    = CASE WHEN friend_req_day = $1 THEN friend_reqs + 1 ELSE 1 END
WHERE id = $2
  AND (friend_req_day IS DISTINCT FROM $1 OR friend_reqs < $3::int)
RETURNING friend_reqs
`

type SpendFriendRequestParams struct {
	Today    pgtype.Date
	PlayerID uuid.UUID
	PerDay   int32
}

// The day's requests, counted on the lord's own row in the same statement that
// spends one, so two taps cannot both be the twentieth.
func (q *Queries) SpendFriendRequest(ctx context.Context, arg SpendFriendRequestParams) (int16, error) {
	row := q.db.QueryRow(ctx, spendFriendRequest, arg.Today, arg.PlayerID, arg.PerDay)
	var friend_reqs int16
	err := row.Scan(&friend_reqs)
	return friend_reqs, err
}

const spendGiftTake = `-- name: SpendGiftTake :one
UPDATE app.players
SET gift_day    = $1,
    gifts_taken = CASE WHEN gift_day = $1 THEN gifts_taken + 1 ELSE 1 END
WHERE id = $2
  AND (gift_day IS DISTINCT FROM $1 OR gifts_taken < $3::int)
RETURNING gifts_taken
`

type SpendGiftTakeParams struct {
	Today    pgtype.Date
	PlayerID uuid.UUID
	PerDay   int32
}

// The day's take, counted on the taker's own row in the same statement that
// spends one. Returns no row when the day is full, which is the guard.
func (q *Queries) SpendGiftTake(ctx context.Context, arg SpendGiftTakeParams) (int16, error) {
	row := q.db.QueryRow(ctx, spendGiftTake, arg.Today, arg.PlayerID, arg.PerDay)
	var gifts_taken int16
	err := row.Scan(&gifts_taken)
	return gifts_taken, err
}

const strikePlayer = `-- name: StrikePlayer :one
UPDATE app.players
SET chat_strikes = CASE
        WHEN chat_strike_at IS NULL OR chat_strike_at < $1::timestamptz THEN 1
        ELSE chat_strikes + 1 END,
    chat_strike_at = now()
WHERE id = $2
RETURNING chat_strikes
`

type StrikePlayerParams struct {
	WindowStart time.Time
	PlayerID    uuid.UUID
}

// A strike, counted inside the window and reset outside it, in one statement so
// the count and the clock can never disagree.
func (q *Queries) StrikePlayer(ctx context.Context, arg StrikePlayerParams) (int16, error) {
	row := q.db.QueryRow(ctx, strikePlayer, arg.WindowStart, arg.PlayerID)
	var chat_strikes int16
	err := row.Scan(&chat_strikes)
	return chat_strikes, err
}

const sweepChat = `-- name: SweepChat :execrows
DELETE FROM app.chat_messages WHERE created_at < $1
`

// The sweeper: the hall keeps what the balance says and no more.
func (q *Queries) SweepChat(ctx context.Context, before time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, sweepChat, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const takeGift = `-- name: TakeGift :one
UPDATE app.gifts SET taken_at = now()
WHERE from_id = $1 AND to_id = $2 AND sent_on = $3
  AND taken_at IS NULL
RETURNING from_id, to_id, sent_on, token, sent_at, taken_at
`

type TakeGiftParams struct {
	FromID uuid.UUID
	ToID   uuid.UUID
	SentOn pgtype.Date
}

// Takes one gift. The WHERE is the guard: a gift already taken returns no row,
// so a double tap grants nothing.
func (q *Queries) TakeGift(ctx context.Context, arg TakeGiftParams) (AppGift, error) {
	row := q.db.QueryRow(ctx, takeGift, arg.FromID, arg.ToID, arg.SentOn)
	var i AppGift
	err := row.Scan(
		&i.FromID,
		&i.ToID,
		&i.SentOn,
		&i.Token,
		&i.SentAt,
		&i.TakenAt,
	)
	return i, err
}

