const upsertKingdomGoal = `-- name: UpsertKingdomGoal :one

INSERT INTO app.kingdom_goals (kingdom_id, day, kind, target, members, ends_at, claim_until)
VALUES ($1, $2, $3, $4,
        $5, $6, $7)
ON CONFLICT (kingdom_id, day) DO UPDATE SET kingdom_id = EXCLUDED.kingdom_id
RETURNING id, kingdom_id, day, kind, target, progress, members, started_at, ends_at, claim_until
`

type UpsertKingdomGoalParams struct {
	KingdomID  uuid.UUID
	Day        pgtype.Date
	Kind       string
	Target     int64
	Members    int16
	EndsAt     time.Time
	ClaimUntil time.Time
}

// ---------------------------------------------------------------------------
// The shared goal
// ---------------------------------------------------------------------------
// The kingdom's goal for a day, made once. The unique key is the rule: two
// lords arriving at the same instant make one goal between them.
func (q *Queries) UpsertKingdomGoal(ctx context.Context, arg UpsertKingdomGoalParams) (AppKingdomGoal, error) {
	row := q.db.QueryRow(ctx, upsertKingdomGoal,
		arg.KingdomID,
		arg.Day,
		arg.Kind,
		arg.Target,
		arg.Members,
		arg.EndsAt,
		arg.ClaimUntil,
	)
	var i AppKingdomGoal
	err := row.Scan(
		&i.ID,
		&i.KingdomID,
		&i.Day,
		&i.Kind,
		&i.Target,
		&i.Progress,
		&i.Members,
		&i.StartedAt,
		&i.EndsAt,
		&i.ClaimUntil,
	)
	return i, err
}
